-- ============================================================
-- Statcast multi-season loader: one table per season
-- Seasons 2015-2026. 2015-2025 share the 119-col schema;
-- 2026 has an extra 'miss_distance' column (120 cols).
-- Run each season's two blocks; skip any you've already loaded.
-- Prereqs (run once per session if needed):
--   SET GLOBAL local_infile = 1;
--   and OPT_LOCAL_INFILE=1 on the connection's Advanced tab.
-- ============================================================

USE statcast;

SET GLOBAL local_infile = 1;

-- ========================= 2015 =========================
CREATE TABLE sc_2015 (
  row_id BIGINT, game_id BIGINT, game_date DATE, game_type VARCHAR(5), year INT,
  event_index INT, pitch_number INT, home_team VARCHAR(5), away_team VARCHAR(5),
  batter_id BIGINT, bat_side VARCHAR(2), batter_name VARCHAR(100), pitcher_id BIGINT,
  pitch_hand VARCHAR(2), pre_runner_1b_id BIGINT, pre_runner_2b_id BIGINT, pre_runner_3b_id BIGINT,
  fielder_2_id BIGINT, fielder_3_id BIGINT, fielder_4_id BIGINT, fielder_5_id BIGINT,
  fielder_6_id BIGINT, fielder_7_id BIGINT, fielder_8_id BIGINT, fielder_9_id BIGINT,
  inning INT, half_inning VARCHAR(10), outs INT, balls INT, strikes INT,
  if_fielding_alignment VARCHAR(30), of_fielding_alignment VARCHAR(30),
  pitch_type VARCHAR(5), arm_angle DOUBLE, ax DOUBLE, ay DOUBLE, az DOUBLE,
  vx0 DOUBLE, vy0 DOUBLE, vz0 DOUBLE, release_pos_x DOUBLE, release_pos_y DOUBLE, release_pos_z DOUBLE,
  release_speed DOUBLE, extension DOUBLE, effective_speed DOUBLE, pfx_x DOUBLE, pfx_z DOUBLE,
  plate_x DOUBLE, plate_z DOUBLE, zone INT, release_spin_rate DOUBLE, spin_axis DOUBLE,
  strike_zone_top DOUBLE, strike_zone_bottom DOUBLE, bat_speed DOUBLE, swing_length DOUBLE,
  launch_speed DOUBLE, launch_angle DOUBLE, expected_woba DOUBLE, expected_babip DOUBLE,
  hit_coord_x DOUBLE, hit_coord_y DOUBLE, hit_distance_sc DOUBLE, bb_type VARCHAR(20),
  hit_location INT, type VARCHAR(2), description VARCHAR(50), events VARCHAR(40),
  woba_denom DOUBLE, woba_value DOUBLE, babip_value DOUBLE, iso_value DOUBLE,
  delta_run_exp DOUBLE, delta_home_win_exp DOUBLE, spin_dir DOUBLE, spin_rate_deprecated DOUBLE,
  break_angle_deprecated DOUBLE, break_length_deprecated DOUBLE, des VARCHAR(255),
  inning_topbot VARCHAR(10), tfs_deprecated VARCHAR(20), tfs_zulu_deprecated VARCHAR(30),
  umpire VARCHAR(50), sv_id VARCHAR(30), launch_speed_angle INT, at_bat_number INT,
  pitch_name VARCHAR(40), home_score INT, away_score INT, bat_score INT, fld_score INT,
  post_away_score INT, post_home_score INT, post_bat_score INT, post_fld_score INT,
  estimated_slg_using_speedangle DOUBLE, delta_pitcher_run_exp DOUBLE, hyper_speed DOUBLE,
